"use client";

import { FlowDiagram } from "@diax/react";
import { Database, Globe, Layers, Server, ShieldCheck, type LucideIcon, Zap } from "lucide-react";

interface ServiceNodeProps {
  icon: LucideIcon;
  title: string;
  desc: string;
  gradient: string;
  metrics: { latency: number; rpm: string };
  status: "healthy" | "degraded";
}

// Extremely rich node representing a microservice with live metrics
const ServiceNode = ({ icon: Icon, title, desc, gradient, metrics, status }: ServiceNodeProps) => (
  <div
    className={`group flex flex-col min-w-[220px] rounded-2xl border border-white/10 bg-black/40 backdrop-blur-xl shadow-2xl transition-all hover:scale-105 hover:border-white/30 overflow-hidden`}
  >
    {/* Header Section */}
    <div className={`p-4 border-b border-white/5 bg-gradient-to-r ${gradient} bg-opacity-10`}>
      <div className="flex items-center justify-between mb-2">
        <div className={`p-2 rounded-lg bg-white/10 shadow-inner`}>
          <Icon className="h-5 w-5 text-white" />
        </div>
        <div className="flex items-center gap-1.5">
          <div
            className={`h-2 w-2 rounded-full ${status === "healthy" ? "bg-emerald-400 shadow-[0_0_8px_#34d399]" : "bg-rose-500 shadow-[0_0_8px_#f43f5e]"}`}
          ></div>
          <span className="text-[10px] text-white/60 font-mono tracking-widest uppercase">
            {status}
          </span>
        </div>
      </div>
      <h3 className="text-base font-bold text-white tracking-wide">{title}</h3>
      <p className="text-xs text-white/60 font-medium">{desc}</p>
    </div>

    {/* Metrics Section */}
    <div className="p-4 grid grid-cols-2 gap-3 bg-white/[0.02]">
      <div className="flex flex-col">
        <span className="text-[10px] text-white/40 uppercase tracking-wider mb-1">Latency</span>
        <div className="flex items-end gap-1">
          <span className="text-sm font-bold text-white font-mono">{metrics.latency}</span>
          <span className="text-[10px] text-white/50 mb-[2px]">ms</span>
        </div>
        {/* Mini chart bar */}
        <div className="w-full h-1 bg-white/10 mt-1.5 rounded-full overflow-hidden">
          <div
            className="h-full bg-indigo-400"
            style={{ width: `${Math.min(100, metrics.latency / 2)}%` }}
          ></div>
        </div>
      </div>
      <div className="flex flex-col border-l border-white/10 pl-3">
        <span className="text-[10px] text-white/40 uppercase tracking-wider mb-1">Requests</span>
        <div className="flex items-end gap-1">
          <span className="text-sm font-bold text-white font-mono">{metrics.rpm}</span>
          <span className="text-[10px] text-white/50 mb-[2px]">/m</span>
        </div>
        {/* Mini chart sparkline mock */}
        <div className="w-full mt-1.5 flex items-end gap-[2px] h-2">
          {[40, 70, 45, 90, 60, 80, 50].map((h) => (
            <div
              key={h}
              className="flex-1 bg-emerald-400/50 rounded-t-sm"
              style={{ height: `${h}%` }}
            ></div>
          ))}
        </div>
      </div>
    </div>
  </div>
);

export default function MicroservicesArch() {
  return (
    <div className="w-full h-full min-h-[600px] flex items-center justify-center relative rounded-xl overflow-hidden bg-[#0A0A0A] p-8">
      {/* SaaS Landing Page style backgrounds */}
      <div className="absolute inset-0 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:32px_32px]"></div>
      <div className="absolute top-1/2 left-1/4 w-[500px] h-[500px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none -translate-y-1/2" />
      <div className="absolute bottom-1/4 right-1/4 w-[400px] h-[400px] bg-cyan-500/10 rounded-full blur-[100px] pointer-events-none" />

      <FlowDiagram
        nodes={[
          {
            id: "client",
            content: (
              <ServiceNode
                icon={Globe}
                title="Web Client"
                desc="Next.js App"
                gradient="from-indigo-600 to-indigo-400"
                status="healthy"
                metrics={{ latency: 45, rpm: "1.2k" }}
              />
            ),
          },
          {
            id: "api",
            content: (
              <ServiceNode
                icon={ShieldCheck}
                title="API Gateway"
                desc="Kong Hub"
                gradient="from-purple-600 to-indigo-500"
                status="healthy"
                metrics={{ latency: 12, rpm: "8.5k" }}
              />
            ),
          },
          {
            id: "auth",
            content: (
              <ServiceNode
                icon={Zap}
                title="Auth Engine"
                desc="OAuth 2.0 Server"
                gradient="from-rose-500 to-orange-400"
                status="healthy"
                metrics={{ latency: 85, rpm: "4.1k" }}
              />
            ),
          },
          {
            id: "users",
            content: (
              <ServiceNode
                icon={Server}
                title="User Service"
                desc="Node.js cluster"
                gradient="from-emerald-500 to-cyan-400"
                status="healthy"
                metrics={{ latency: 120, rpm: "3.2k" }}
              />
            ),
          },
          {
            id: "orders",
            content: (
              <ServiceNode
                icon={Layers}
                title="Orders API"
                desc="Go Fiber"
                gradient="from-blue-600 to-indigo-500"
                status="healthy"
                metrics={{ latency: 35, rpm: "1.8k" }}
              />
            ),
          },
          {
            id: "db",
            content: (
              <ServiceNode
                icon={Database}
                title="Global DB"
                desc="PostgreSQL Dist"
                gradient="from-slate-600 to-slate-400"
                status="healthy"
                metrics={{ latency: 5, rpm: "12k" }}
              />
            ),
          },
        ]}
        relations={[
          "client->|HTTPS|api",
          "api->auth",
          "api->users",
          "api->orders",
          "users->db",
          "orders->db",
        ]}
        direction="horizontal"
        centered
        density="spacious"
      />
    </div>
  );
}
